CREATE TABLE component (
	id INTEGER NOT NULL, 
	uuid VARCHAR(36) NOT NULL, 
	component_type VARCHAR(32) NOT NULL, 
	label TEXT NOT NULL, 
	product_id INTEGER, 
	serial_number TEXT, 
	prior_usage VARCHAR(16) NOT NULL, 
	purchase_date VARCHAR(10), 
	price_cents INTEGER, 
	status VARCHAR(16) NOT NULL, 
	retired_on VARCHAR(10), 
	retire_reason TEXT, 
	notes TEXT, 
	created_at VARCHAR(20) NOT NULL, 
	updated_at VARCHAR(20) NOT NULL, specs_json TEXT DEFAULT '{}' NOT NULL, disposition VARCHAR(20) DEFAULT 'STORED' NOT NULL, disposition_on VARCHAR(10), purchase_session_id INTEGER, from_stock_txn_id INTEGER, storage_location TEXT, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_component_prior_usage CHECK (prior_usage IN ('NEW','RECORDED','UNKNOWN')), 
	CONSTRAINT ck_component_status CHECK (status IN ('ACTIVE','RETIRED')), 
	FOREIGN KEY(product_id) REFERENCES product (id), 
	CONSTRAINT uq_component_type_label UNIQUE (component_type, label), 
	UNIQUE (uuid)
);
