CREATE TABLE ride_equipment (
	ride_id INTEGER NOT NULL, 
	slot VARCHAR(32) NOT NULL, 
	component_id INTEGER, 
	note TEXT, 
	PRIMARY KEY (ride_id, slot), 
	FOREIGN KEY(component_id) REFERENCES component (id), 
	FOREIGN KEY(ride_id) REFERENCES ride (id)
);
CREATE TABLE ride_flag (
	id INTEGER NOT NULL, 
	ride_id INTEGER NOT NULL, 
	code VARCHAR(32) NOT NULL, 
	slot VARCHAR(32), 
	detail TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(ride_id) REFERENCES ride (id)
);
INSERT INTO "ride_flag" VALUES(1,13,'UNCERTAIN_ASSIGNMENT',NULL,'Might have been the BMC');
CREATE TABLE ride_override (
	ride_id INTEGER NOT NULL, 
	field VARCHAR(32) NOT NULL, 
	value_json TEXT NOT NULL, 
	set_at VARCHAR(20) NOT NULL, 
	PRIMARY KEY (ride_id, field), 
	FOREIGN KEY(ride_id) REFERENCES ride (id)
);
CREATE TABLE ride_source (
	id INTEGER NOT NULL, 
	ride_id INTEGER NOT NULL, 
	source_kind VARCHAR(16) NOT NULL, 
	source_account VARCHAR(64) NOT NULL, 
	source_ref VARCHAR(128) NOT NULL, 
	values_json TEXT NOT NULL, 
	payload_hash VARCHAR(64) NOT NULL, 
	import_batch_id INTEGER, 
	first_seen_at VARCHAR(20) NOT NULL, 
	last_seen_at VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(import_batch_id) REFERENCES import_batch (id), 
	FOREIGN KEY(ride_id) REFERENCES ride (id), 
	UNIQUE (ride_id), 
	CONSTRAINT uq_ride_source_identity UNIQUE (source_kind, source_account, source_ref)
);
CREATE TABLE service_rule (
	id INTEGER NOT NULL, 
	uuid VARCHAR(36) NOT NULL, 
	rule_code VARCHAR(48) NOT NULL, 
	name TEXT NOT NULL, 
	component_type VARCHAR(32), 
	component_id INTEGER, 
	action_code VARCHAR(32) NOT NULL, 
	"trigger" VARCHAR(16) NOT NULL, 
	interval_km FLOAT, 
	interval_months INTEGER, 
	window_min_km FLOAT, 
	window_max_km FLOAT, 
	cycle_action_code VARCHAR(32), 
	reset_actions_json TEXT NOT NULL, 
	warn_km FLOAT, 
	warn_days INTEGER, 
	origin VARCHAR(16) NOT NULL, 
	active BOOLEAN NOT NULL, 
	notes TEXT, 
	created_at VARCHAR(20) NOT NULL, 
	updated_at VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_rule_origin CHECK (origin IN ('DEFAULT','MANUFACTURER','PERSONAL')), 
	CONSTRAINT ck_rule_window CHECK (trigger <> 'CYCLE_WINDOW' OR (window_min_km IS NOT NULL AND window_max_km >= window_min_km AND cycle_action_code IS NOT NULL)), 
	CONSTRAINT ck_rule_interval CHECK (trigger <> 'INTERVAL' OR interval_km IS NOT NULL OR interval_months IS NOT NULL), 
	CONSTRAINT ck_rule_trigger CHECK (trigger IN ('INTERVAL','CYCLE_WINDOW')), 
	CONSTRAINT ck_rule_target CHECK ((component_type IS NULL) <> (component_id IS NULL)), 
	FOREIGN KEY(component_id) REFERENCES component (id), 
	UNIQUE (uuid)
);
